func:
// =========================================
// 老方案必需的后处理代码
// 每新增/修改一个点位 → 必须改这段代码 → 重新部署
// =========================================
var pointConfig = {
    "D0":  {name: "炉温1区",   slope: 0.1, unit: "℃"},
    "D1":  {name: "炉温2区",   slope: 0.1, unit: "℃"},
    "D2":  {name: "炉温3区",   slope: 0.1, unit: "℃"},
    "D3":  {name: "炉温4区",   slope: 0.1, unit: "℃"},
    "D4":  {name: "炉温5区",   slope: 0.1, unit: "℃"},
    "D5":  {name: "压力A",     slope: 1,   unit: "kPa"},
    "D6":  {name: "压力B",     slope: 1,   unit: "kPa"},
    "D7":  {name: "流量1",     slope: 0.01,unit: "m³/h"},
    "D8":  {name: "流量2",     slope: 0.01,unit: "m³/h"},
    "D9":  {name: "传送带速度", slope: 0.1, unit: "m/s"},
};

var output = {};
for (var addr in msg.payload) {
    if (msg.payload.hasOwnProperty(addr)) {
        var cfg = pointConfig[addr];
        if (cfg) {
            output[cfg.name] = {
                value: +(msg.payload[addr] * cfg.slope).toFixed(1),
                unit: cfg.unit
            };
        } else {
            output[addr] = msg.payload[addr];
        }
    }
}
msg.payload = output;
return msg;
